import re
import nltk
nltk.download('stopwords')
from nltk.corpus import stopwords
from collections import Counter
# Constants
STOPWORDS = set(stopwords.words('english'))

def task_func(text, n=2):
    """
    Remove stopwords and duplicate tokens from text, then count n-grams.

    Args:
        text: Input text string.
        n: Size of the n-grams (default is 2 for bigrams).

    Returns:
        dict: A dictionary mapping n-gram strings to their counts.
    """
    if text is None:
        return {}
    if not isinstance(text, str):
        text = str(text)

    if not isinstance(n, int) or n <= 0:
        return {}

    # Normalize and tokenize
    tokens = re.findall(r"\b\w+\b", text.lower())

    # Remove stopwords
    tokens = [token for token in tokens if token not in STOPWORDS]

    # Remove duplicate tokens while preserving order
    seen = set()
    unique_tokens = []
    for token in tokens:
        if token not in seen:
            seen.add(token)
            unique_tokens.append(token)

    # If not enough tokens for one n-gram, return empty dict
    if len(unique_tokens) < n:
        return {}

    # Build n-grams and count them
    ngrams = (
        " ".join(unique_tokens[i:i + n])
        for i in range(len(unique_tokens) - n + 1)
    )
    return dict(Counter(ngrams))
